content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-12-finance-011

=== 用户原始指令 (query.txt) ===
做个预算仪表盘卡片,数据用示例就行文案固定别动,简洁素净点。中间一个环形图,左右分区显示本月各类数据(消费、收入、结余),接近阈值的要黄标提示。纯文字加色块,要点能跳到天气,纵向排多行。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "做个预算仪表盘卡片,数据用示例就行文案固定别动,简洁素净点。中间一个环形图,左右分区显示本月各类数据(消费、收入、结余),接近阈值的要黄标提示。纯文字加色块,要点能跳到天气,纵向排多行。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "budget": {
        "title": {
          "type": "string",
          "description": "卡片标题，固定显示预算仪表盘。",
          "sampleValue": "预算仪表盘"
        },
        "progressValue": {
          "type": "number",
          "description": "本月预算已使用比例数值，用于环形图进度。",
          "sampleValue": 82
        },
        "progressTotal": {
          "type": "number",
          "description": "预算进度总量，作为环形图满刻度。",
          "sampleValue": 100
        },
        "progressText": {
          "type": "string",
          "description": "本月预算已使用比例展示文本。",
          "sampleValue": "82%"
        },
        "expenseLabel": {
          "type": "string",
          "description": "本月消费指标标签。",
          "sampleValue": "消费"
        },
        "expenseValue": {
          "type": "string",
          "description": "本月消费金额短展示。",
          "sampleValue": "5.6k"
        },
        "warningLabel": {
          "type": "string",
          "description": "接近阈值时的黄色提示标签。",
          "sampleValue": "黄标"
        },
        "incomeLabel": {
          "type": "string",
          "description": "本月收入指标标签。",
          "sampleValue": "收入"
        },
        "incomeValue": {
          "type": "string",
          "description": "本月收入金额短展示。",
          "sampleValue": "8.2k"
        },
        "balanceLabel": {
          "type": "string",
          "description": "本月结余指标标签。",
          "sampleValue": "结余"
        },
        "balanceValue": {
          "type": "string",
          "description": "本月结余金额短展示。",
          "sampleValue": "2.6k"
        },
        "actionLabel": {
          "type": "string",
          "description": "跳转天气的固定入口文案。",
          "sampleValue": "看天气"
        }
      }
    }
  },
  "assetCandidates": []
}

